using System;using System.Linq;using System.Collections.Generic;using IdleIntelligence.Core;using UnityEngine;using UnityEngine.UI;using UnityEngine.EventSystems;using UnityEngine.InputSystem;
namespace IdleIntelligence.Runtime
{
 public sealed class PrestigeNetworkView:MonoBehaviour,IBeginDragHandler,IDragHandler,IEndDragHandler,IScrollHandler
 {
  public RectTransform World,Viewport;public PrestigeNodeView NodePrefab;public Sprite[] NodeSprites,AxiomSprites;public bool IsAxiom {get;private set;}
  PrestigeNode[] Catalog=>IsAxiom?MetaBalance.Axioms.Select(n=>new PrestigeNode(n.Id,n.Name,n.Costs[0],n.Branch,n.Depth,n.Description,n.X,n.Y)).ToArray():PrestigeBalance.Nodes;
  Sprite NodeSprite(int i)=>IsAxiom?AxiomSprites[i]:NodeSprites[i];public Text Ledger;public Button ResetButton;public PrestigePulse Pulse;Button companyMilestone;readonly List<PrestigeNodeView> nodes=new List<PrestigeNodeView>();GameRuntime game;GameObject detail;Transform detailContent;float zoom=(float)PrestigeBalance.ZoomInitial,blockClickUntil;Vector2 touchA,touchB;bool twoTouches;long seenRevision=-1;int lastCount=-1;
  public float Zoom=>zoom;public int NodeCount=>nodes.Count;public bool GestureBlocked=>twoTouches||Time.unscaledTime<blockClickUntil;
  public void Initialize(GameRuntime runtime)
  {
   game=runtime;Pulse.transform.SetParent(GetComponentInParent<Canvas>().transform,false);WorkshopUIFactory.Fill((RectTransform)Pulse.transform);Pulse.gameObject.AddComponent<SafeArea>();BuildNodes();Home();ResetButton.onClick.AddListener(PerformReset);transform.Find("NetworkTools/ZoomOut").GetComponent<Button>().onClick.AddListener(()=>ZoomAt(zoom/1.15f,Vector2.zero));transform.Find("NetworkTools/ZoomIn").GetComponent<Button>().onClick.AddListener(()=>ZoomAt(zoom*1.15f,Vector2.zero));transform.Find("NetworkTools/Home").GetComponent<Button>().onClick.AddListener(Home);transform.Find("NetworkTools/ReducedPrestigeMotion").GetComponent<Button>().onClick.AddListener(()=>{game.Act(s=>{var n=s.Copy();n.Workshop.reducedMotion=!n.Workshop.reducedMotion;n.Settings.effects=!n.Workshop.reducedMotion;return n;});Pulse.Cancel();});
   var pause=WorkshopUIFactory.Button("PauseAutomaticResets",transform,"Pause automatic resets",()=>game.Act(ResetControls.Pause));pause.interactable=game.Writable&&!ChallengeRules.Active(game.State);var layer=WorkshopUIFactory.Button("NetworkLayer",transform,"Axiome",()=>SetLayer(!IsAxiom));layer.transform.SetAsFirstSibling();
   companyMilestone=WorkshopUIFactory.Button("CompanyAccessMilestone",transform,
     "Companies · 1.000 INT",()=>game.UserShow("company"));
   companyMilestone.transform.SetAsFirstSibling();
   for(int i=0;i<6;i++){int branch=i;transform.Find("Branches/Branch"+i).GetComponent<Button>().onClick.AddListener(()=>CenterBranch(branch));}Refresh();
  }
  void BuildNodes(){foreach(var n in nodes){n.gameObject.SetActive(false);Destroy(n.gameObject);}nodes.Clear();for(int i=0;i<Catalog.Length;i++){var d=Catalog[i];var view=Instantiate(NodePrefab,World);view.Id=d.Id;view.name="int-node-"+d.Id;((RectTransform)view.transform).anchoredPosition=new Vector2((float)d.X,(float)d.Y);view.Title.text=d.Id+" · "+d.Name;view.Art.sprite=NodeSprite(i);view.Button.onClick.AddListener(()=>{if(!GestureBlocked)OpenNode(d.Id);});nodes.Add(view);}var wires=World.GetComponentInChildren<NetworkWires>();wires.Nodes=Catalog;wires.SetVerticesDirty();seenRevision=-1;lastCount=-1;}
  public void SetLayer(bool axiom){if(axiom&&game.State.Meta.resets==0&&MetaRules.Reward(game.State).CompareTo(ScientificNumber.One)<0)return;Cancel();IsAxiom=axiom;BuildNodes();for(int i=0;i<6;i++){var b=transform.Find("Branches/Branch"+i);b.gameObject.SetActive(!axiom||i<4);if(axiom&&i<4)b.GetComponentInChildren<Text>().text=new[]{"Resonanz","Archive","Material","Modelle"}[i];else b.GetComponentInChildren<Text>().text=new[]{"Hardware","Training","Forschung","Werkstatt","Impulse","Erkenntnis"}[i];}World.Find("INTCore").GetComponentInChildren<Text>().text=axiom?"AXIOM":"INT";Home();Refresh();}
  public void Home(){zoom=(float)PrestigeBalance.ZoomInitial;World.localScale=Vector3.one*zoom;World.anchoredPosition=Vector2.zero;}
  public void CenterBranch(int branch){var p=Catalog.First(n=>n.Branch==branch);World.anchoredPosition=-new Vector2((float)p.X,(float)p.Y)*zoom;}
  public void ZoomAt(float target,Vector2 pivot){float next=Mathf.Clamp(target,(float)PrestigeBalance.ZoomMin,(float)PrestigeBalance.ZoomMax);float ratio=next/zoom;World.anchoredPosition=pivot-(pivot-World.anchoredPosition)*ratio;zoom=next;World.localScale=Vector3.one*zoom;Clamp();}
  public void Pinch(Vector2 oldA,Vector2 oldB,Vector2 nextA,Vector2 nextB){var before=(oldA+oldB)/2;var after=(nextA+nextB)/2;ZoomAt(zoom*Vector2.Distance(nextA,nextB)/Mathf.Max(1,Vector2.Distance(oldA,oldB)),before);World.anchoredPosition+=after-before;Clamp();blockClickUntil=Time.unscaledTime+.25f;}
  void Clamp(){var p=World.anchoredPosition;float extent=1850*zoom;p.x=Mathf.Clamp(p.x,-extent,extent);p.y=Mathf.Clamp(p.y,-extent,extent);World.anchoredPosition=p;}
  public void OnBeginDrag(PointerEventData e){blockClickUntil=Time.unscaledTime+.25f;}
  public void OnDrag(PointerEventData e){if(twoTouches)return;World.anchoredPosition+=e.delta/GetComponentInParent<Canvas>().scaleFactor;Clamp();blockClickUntil=Time.unscaledTime+.25f;}
  public void OnEndDrag(PointerEventData e){blockClickUntil=Time.unscaledTime+.25f;}
  public void OnScroll(PointerEventData e){RectTransformUtility.ScreenPointToLocalPointInRectangle(Viewport,e.position,e.pressEventCamera,out var local);ZoomAt(zoom*Mathf.Pow(1.15f,e.scrollDelta.y),local);}
  void Update()
  {
   if(game==null)return;var touches=Touchscreen.current?.touches.Where(t=>t.press.isPressed).Take(2).ToArray();if(touches!=null&&touches.Length==2){RectTransformUtility.ScreenPointToLocalPointInRectangle(Viewport,touches[0].position.ReadValue(),null,out var a);RectTransformUtility.ScreenPointToLocalPointInRectangle(Viewport,touches[1].position.ReadValue(),null,out var b);if(twoTouches)Pinch(touchA,touchB,a,b);touchA=a;touchB=b;twoTouches=true;blockClickUntil=Time.unscaledTime+.25f;}else twoTouches=false;Refresh();
  }
  void Refresh(){var s=game.State;Ledger.text=IsAxiom?"AXIOME "+ScientificNumber.FromData(s.Meta.available)+" · insgesamt "+ScientificNumber.FromData(s.Meta.total)+"\nNächster Axiomreset: +"+MetaRules.Reward(s):"INT "+s.Prestige.Free+" · insgesamt "+s.Prestige.Total+"\nNächstes Prestige: +"+PrestigeRules.Claim(s)+" INT · Lauf "+(s.Prestige.resets+1);ResetButton.GetComponentInChildren<Text>().text=IsAxiom?"Axiomreset · Erhaltung prüfen":"Prestige · neuen Lauf starten";ResetButton.interactable=game.Writable&&(!ChallengeRules.Active(s)||!IsAxiom&&PrestigeRules.Claim(s).CompareTo(ChallengeRules.Current(s).MinimumINT)>=0)&&(IsAxiom?MetaRules.Reward(s):PrestigeRules.Claim(s)).CompareTo(ScientificNumber.One)>=0;if(companyMilestone!=null){
      companyMilestone.gameObject.SetActive(!IsAxiom);
      var text=companyMilestone.GetComponentInChildren<Text>();
      bool eligible=CompanyAccess.LocallyEligible(s);
      text.text=eligible?"◆ COMPANIES · 1.000 INT erreicht · Mira erklärt":
        "COMPANIES · ab 1.000 Gesamt-INT · Info";
      companyMilestone.interactable=game.Writable;
   }
   var layer=transform.Find("NetworkLayer").GetComponent<Button>();layer.GetComponentInChildren<Text>().text=IsAxiom?"Zum INT-Netz":s.Meta.resets>0||MetaRules.Reward(s).CompareTo(ScientificNumber.One)>=0?"Zum Axiomnetz":"Axiome: 30 bekannte Knoten und genug Zyklus-INT";layer.interactable=IsAxiom||s.Meta.resets>0||MetaRules.Reward(s).CompareTo(ScientificNumber.One)>=0;if(seenRevision==s.Prestige.revision&&lastCount==s.Workshop.nodes.Length)return;seenRevision=s.Prestige.revision;lastCount=s.Workshop.nodes.Length;foreach(var view in nodes){var d=Catalog.First(n=>n.Id==view.Id);var cost=IsAxiom?MetaRules.AxiomCost(s,d.Id):ScientificNumber.From(d.Cost);bool owned=IsAxiom?cost==null:PrestigeRules.Has(s,d.Id),affordable=cost!=null&&(IsAxiom?ScientificNumber.FromData(s.Meta.available):s.Prestige.Free).CompareTo(cost)>=0;view.Price.text=IsAxiom?"Lv "+MetaRules.Level(s,d.Id)+" · "+(cost==null?"Max":cost+" A"):owned?"Aktiv":cost+" INT";var c=NetworkWires.Colors[d.Branch];view.Panel.color=owned?c*.62f:affordable?c*.3f:new Color(.07f,.12f,.18f);view.Price.color=owned||affordable?Color.white:new Color(.65f,.72f,.8f);}}
  public void PerformReset(){if(IsAxiom){ShowAxiomPreview();return;}long ticket=game.State.Prestige.revision;var gain=PrestigeRules.Claim(game.State);if(game.Act(s=>PrestigeRules.Reset(s,ticket),"prestige")){CloseDetail();Pulse.Play("Neuer Lauf · +"+ScientificNumber.FromData(game.State.Prestige.lastGain)+" INT",game.State.Workshop.reducedMotion);Refresh();}}
  public void Cancel(){Pulse.Cancel();CloseDetail();twoTouches=false;}
  void OnDisable(){Cancel();}void OnDestroy(){if(detail!=null)Destroy(detail);if(Application.isPlaying&&Pulse!=null)Destroy(Pulse.gameObject);}
  public void OpenNode(string id)
  {
   Pulse.Cancel();CloseDetail();var d=Catalog.First(n=>n.Id==id);var s=game.State;BeginDetail();
   WorkshopUIFactory.Label("NodeName",detailContent,d.Id+" · "+d.Name,19,58);var art=WorkshopUIFactory.Node("NodeArt",detailContent,typeof(Image));WorkshopUIFactory.Size(art,96);art.GetComponent<Image>().sprite=NodeSprite(Array.FindIndex(Catalog,n=>n.Id==id));art.GetComponent<Image>().preserveAspect=true;art.GetComponent<Image>().useSpriteMesh=true;WorkshopUIFactory.Label("Description",detailContent,d.Description+"\n\nPreis: "+(IsAxiom?MetaRules.AxiomCost(s,id)?.ToString()??"Maximalstufe":ScientificNumber.From(d.Cost).ToString())+(IsAxiom?" Axiome":" INT")+". Verbindungen sind keine Kaufvoraussetzungen.",15,190);
   if(!IsAxiom&&PrestigeBalance.LegacyItemBonuses[d.Id]>0)WorkshopUIFactory.Label("AdditionalItemEffect",detailContent,"Allgemeine Itemboni: +"+(PrestigeBalance.LegacyItemBonuses[d.Id]*100)+" % im gemeinsamen Zusatzpool der aktuellen Regeln.",14,64);

   var cost=IsAxiom?MetaRules.AxiomCost(s,id):ScientificNumber.From(d.Cost);bool owned=IsAxiom?cost==null:PrestigeRules.Has(s,id);var buy=WorkshopUIFactory.Button("BuyINTNode",detailContent,owned?"Bereits enthalten / Maximum":"Kaufen · "+cost+(IsAxiom?" Axiome":" INT"),()=>{if(game.Act(v=>IsAxiom?MetaRules.Buy(v,id):PrestigeRules.Buy(v,id),"node"))OpenNode(id);});buy.interactable=game.Writable&&!ChallengeRules.Active(s)&&!owned&&cost!=null&&(IsAxiom?ScientificNumber.FromData(s.Meta.available):s.Prestige.Free).CompareTo(cost)>=0;
   if(IsAxiom)MetaSettings.Build(detailContent,game,id,()=>OpenNode(id));else PrestigeSettings.Build(detailContent,game,id,()=>OpenNode(id));
  }
  void BeginDetail(){detail=WorkshopUIFactory.Node("INTDetails",GetComponentInParent<Canvas>().transform,typeof(Image));WorkshopUIFactory.Fill((RectTransform)detail.transform);var overlay=detail.AddComponent<Canvas>();overlay.overrideSorting=true;overlay.sortingOrder=100;detail.AddComponent<GraphicRaycaster>();detail.GetComponent<Image>().color=new Color(.025f,.045f,.07f,.98f);detail.AddComponent<SafeArea>();
   var panel=WorkshopUIFactory.Vertical("Panel",detail.transform);var pr=(RectTransform)panel.transform;pr.anchorMin=new Vector2(.05f,.05f);pr.anchorMax=new Vector2(.95f,.95f);pr.offsetMin=pr.offsetMax=Vector2.zero;panel.GetComponent<VerticalLayoutGroup>().padding=new RectOffset(10,10,10,10);WorkshopUIFactory.Button("CloseINTDetails",panel.transform,"Schließen",CloseDetail);
   var scroll=WorkshopUIFactory.Node("Scroll",panel.transform,typeof(ScrollRect));scroll.AddComponent<LayoutElement>().flexibleHeight=1;var viewport=WorkshopUIFactory.Node("Viewport",scroll.transform,typeof(RectMask2D));WorkshopUIFactory.Fill((RectTransform)viewport.transform);var content=WorkshopUIFactory.Vertical("Content",viewport.transform);detailContent=content.transform;var cr=(RectTransform)content.transform;cr.anchorMin=new Vector2(0,1);cr.anchorMax=Vector2.one;cr.pivot=new Vector2(.5f,1);cr.offsetMin=cr.offsetMax=Vector2.zero;content.AddComponent<ContentSizeFitter>().verticalFit=ContentSizeFitter.FitMode.PreferredSize;var sr=scroll.GetComponent<ScrollRect>();sr.content=cr;sr.viewport=(RectTransform)viewport.transform;sr.horizontal=false;sr.movementType=ScrollRect.MovementType.Clamped;
}
  void ShowAxiomPreview(){CloseDetail();BeginDetail();WorkshopUIFactory.Label("ResetRetention",detailContent,"Axiomreset: +"+MetaRules.Reward(game.State)+" Axiome\n\n"+MetaRules.ResetPreview(game.State),15,680);long ticket=game.State.Prestige.revision;WorkshopUIFactory.Button("ConfirmAxiomReset",detailContent,"Axiomreset verbindlich ausführen",()=>{var gain=MetaRules.Reward(game.State);if(game.Act(s=>MetaRules.AxiomReset(s,ticket),"axiom-reset")){CloseDetail();Pulse.Play("Axiomzyklus · +"+gain+" Axiome",game.State.Workshop.reducedMotion);Refresh();}});}

  public void CloseDetail(){if(detail!=null){detail.SetActive(false);Destroy(detail);detail=null;}}
